"""Correct realization granularity only; all r7 applicability conditions unchanged."""
from pathlib import Path
import copy,json,sys
H=Path(__file__).resolve().parent;R=H.parents[2]
sys.path.insert(0,str(R/'src'))
from kg_pipeline.io import read,save,sha
def main():
 src=R/'knowledge/authored/semantic_grammar_20261104_r7/private/graph.json';g=read(src);before=copy.deepcopy(g);nodes={n['id']:n for n in g['nodes']};changed=[]
 for rid in ['SEM_DECL_HAEYE_EO','SEM_SUP_POLITE_Q_EO']:
  fs=[e['target'] for e in g['edges'] if e['source']==rid and e['relation']=='REALIZES'];assert len(fs)==1
  n=nodes[fs[0]];p=n['properties'];old=copy.deepcopy(p)
  p.update(form='-예',unit='right_edge_politeness_marker',operation='replace_final_yo_with_ye_preserve_inflected_prefix',includes_copula=False,allomorphs=[],composition='원문 목표 어절은 이미 어간·시제·높임이 활용된 형태다. 맨 끝의 요만 예로 바꾸고, 그 앞의 모든 글자는 그대로 보존한다. 어간부터 다시 조합하거나 어를 새로 붙이지 않는다. 이 규칙은 KG 조건을 통과한 아/어요 구성에만 적용한다.',realization_basis='D02 PDF203 hae+ye and D05 PDF26 a/eo-ye; source-surface-preserving operationalization, not attestation of every whole word')
  p['prefix_preservation_scope']='implementation choice; dialect phonological and lexical variants of the hae-form are not generated by this operation'
  changed.append({'rule_id':rid,'node_id':n['id'],'before':old,'after':copy.deepcopy(p)})
 g['version']='semantic_grammar_20261104_r8';g['generation_policy']['realization_revision']='two EO realizations: change politeness suffix while retaining observed inflected source'
 assert g['edges']==before['edges']
 ids={x['node_id'] for x in changed};assert all(n==nodes[n['id']] for n in before['nodes'] if n['id'] not in ids)
 out=R/'knowledge/authored/semantic_grammar_20261104_r8/private';save(out/'graph.json',g);save(out/'change_ledger.json',{'parent_sha256':sha(src.read_bytes()),'changed':changed,'conditions_changed':False,'edges_changed':False,'new_linguistic_facts':False,'existing_rule_realization_changed':['SEM_DECL_HAEYE_EO'],'neo4j_imported':False})
 print(json.dumps({'version':g['version'],'changed_realization_nodes':list(ids),'conditions_and_edges_unchanged':True},ensure_ascii=False))
if __name__=='__main__':main()
